223	// A changed message is also written back to the session's last user entry.
224	async function rewriteUserMessage(
225	  session: ChatSession,
226	  userMessage: string,
227	  hook: (session: ChatSession, userMessage: string) => Promise<string>
228	): Promise<string> {
229	  const modified = await hook(session, userMessage);
230	  if (modified === userMessage) return userMessage;
231	
232	  updateLastUserContent(session, modified);
233	  return modified;
234	}
